1	// Package projection renders the markdown and YAML surfaces from a Store.
2	// Projections are read-only build outputs: banner-stamped where the format
3	// allows, regenerated write-through, and compared before writing so a
4	// byte-identical render never touches mtime (the frozen SSE behavior must
5	// not fire on no-op rebuilds).
6	package projection
7	
8	import (
9		"bytes"
10		"fmt"
11		"os"
12		"path/filepath"
13		"sort"
14		"strings"
15	
16		"github.com/prestontallen/ai-devboard/worklog/internal/model"
17		"github.com/prestontallen/ai-devboard/worklog/internal/store"
18	)
19	
20	// Banner is the build-output marker emitted at the top of the markdown
21	// surfaces. It lives in internal/model so the parser can strip it without
22	// depending on this package (see model.Banner).
23	const Banner = model.Banner
24	
25	func banner(b *bytes.Buffer) { b.WriteString(Banner + "\n") }
26	
27	// Render produces every projection of s as an in-memory map of
28	// slash-separated relative path to content: WORK.md, notes/<slug>.md,
29	// archive/<month>.md, FEEDBACK.md, devboard/<repo>/<slug>.yaml (with
30	// _archive/ for board-archived tasks).
31	//
32	// INDEX.md is deliberately absent: it is produced by running the real
33	// reindex over this output, so the projection IS that code's output
34	// rather than a reimplementation of it.
35	func Render(s store.Store) (map[string][]byte, error) {
36		tickets, err := s.Tickets()
37		if err != nil {
38			return nil, err
39		}
40		out := map[string][]byte{"WORK.md": WorkMD(tickets)}
41	
42		for _, t := range tickets {
43			if t.NotesPreamble == "" && len(t.NoteEntries) == 0 {
44				continue
45			}
46			if t.Slug == "" {
47				continue // slug-less quick-capture entities carry no notes file
48			}
49			out["notes/"+t.Slug+".md"] = NotesFile(t)
50		}
51	
52		months := map[string][]*store.Ticket{}
53		for _, t := range tickets {
54			if t.Archived && t.ArchiveMonth != "" {
55				months[t.ArchiveMonth] = append(months[t.ArchiveMonth], t)
56			}
57		}
58		for month, ts := range months {
59			out["archive/"+month+".md"] = ArchiveMonth(month, ts, tickets)
60		}
61	
62		fb, err := s.Feedback()
63		if err != nil {
64			return nil, err
65		}
66		// Always emitted, even with zero entries. Gating on len(fb) made
67		// FEEDBACK.md invisible to BOTH EditedIn and RenderTo whenever the
68		// store happened to hold no feedback — so a hand-edited or
69		// merely-unread friction log was neither protected from a re-render
70		// nor rewritten by one, until the first entry arrived and replaced it
71		// wholesale. A projection's existence is a property of the surface,
72		// not of its row count.
73		out["FEEDBACK.md"] = FeedbackMD(fb)
74	
75		for _, t := range tickets {
76			if !t.BoardTracked || t.ParentID != "" {
77				continue // children render inside their epic's file
78			}
79			kids, err := s.Children(t.ID)
80			if err != nil {
81				return nil, err
82			}
83			// A child never gets its own top-level file (see the skip above),
84			// so its own BoardTracked flag doesn't gate anything here — the
85			// epic's roster is the only surface a child ever appears on, and
86			// it's the full history: pending, active, and done children alike
87			// (a done child leaves ## Now but stays on the epic's card as
88			// completed history until the epic itself is archived).
89			// Repo attribution heals here (ratified OQ2): the canonical repo
90			// field decides the group directory, never the writer's cwd.
91			repo := t.Repo
92			if repo == "" {
93				repo = "unknown"
94			}
95			dir := "devboard/" + repo
96			if t.BoardArchived {
97				dir += "/_archive"
98			}
99			out[dir+"/"+t.Slug+".yaml"] = BoardYAML(t, kids)
100		}
101		return out, nil
102	}
103	
104	// Layout locates the two directories the projections actually split
105	// across in a live install: the worklog dir (WORK.md, notes/, archive/,
106	// FEEDBACK.md) and the devboard dir, which is a sibling rather than a
107	// subdirectory. Render's map is rooted at a single tree, so this is where
108	// the "devboard/" prefix gets redirected.
109	type Layout struct {
110		WorklogDir  string
111		DevboardDir string
112	}
113	
114	// SingleRoot is the layout the staged copies and tests use, where the
115	// devboard tree sits under the worklog root as Render names it.
116	func SingleRoot(root string) Layout {
117		return Layout{WorklogDir: root, DevboardDir: filepath.Join(root, "devboard")}
118	}
119	
120	func (l Layout) path(rel string) string {
121		if after, ok := strings.CutPrefix(rel, "devboard/"); ok {
122			return filepath.Join(l.DevboardDir, filepath.FromSlash(after))
123		}
124		return filepath.Join(l.WorklogDir, filepath.FromSlash(rel))
125	}
126	
127	// RenderTo writes every projection of s into the two directories l names.
128	func RenderTo(s store.Store, l Layout) error {
129		files, err := Render(s)
130		if err != nil {
131			return err
132		}
133		for rel, content := range files {
134			if err := writeIfChanged(l.path(rel), content); err != nil {
135				return err
136			}
137			// The store owns where a board task file lives, so archiving is a
138			// re-render rather than a rename (adb-archive-store-desync). Clearing
139			// the path the ticket just left is the other half of that: without it
140			// the board shows one task twice, once per path.
141			if sib := boardSibling(rel); sib != "" {
142				if err := os.Remove(l.path(sib)); err != nil && !os.IsNotExist(err) {
143					return fmt.Errorf("clearing %s: %w", sib, err)
144				}
145			}
146		}
147		return nil
148	}
149	
150	// archiveSegment is the directory an archived board task file lives in,
151	// relative to its repo dir.
